class Solution {
    public double maxProbability(int n,int[][] edges,double[] succProb,int start,int end){
        List<double[]>[] graph=new List[n];
        for(int i=0;i<n;i++)graph[i]=new ArrayList<>();
        for(int i=0;i<edges.length;i++){
            graph[edges[i][0]].add(new double[]{
                edges[i][1],succProb[i]
            });
            graph[edges[i][1]].add(new double[]{
                edges[i][0],succProb[i]
            });
        }
        double[] best=new double[n];
        best[start]=1;
        PriorityQueue<double[]> heap=new PriorityQueue<>((a,b)->Double.compare(b[0],a[0]));
        heap.offer(new double[]{
            1,start
        });
        while(!heap.isEmpty()){
            double[] state=heap.poll();
            double probability=state[0];
            int node=(int)state[1];
            if(probability<best[node])continue;
            if(node==end)return probability;
            for(double[] edge:graph[node]){
                int next=(int)edge[0];
                double candidate=probability*edge[1];
                if(candidate>best[next]){
                    best[next]=candidate;
                    heap.offer(new double[]{
                        candidate,next
                    });
                }
            }
        }
        return 0;
    }
}

